import pyomo.environ as pyo

DATA = {
    "products": [0, 1, 2],
    "periods": [0, 1, 2, 3, 4, 5],
    # Cumulative demands (index by product)
    "cum_demand": {
        0: [75, 141, 241, 315, 386, 469],
        1: [65, 151, 228, 286, 338, 390],
        2: [57, 143, 193, 263, 363, 428],
    },
    # Production cost per unit
    "prod_cost": {
        0: [42, 47, 41, 40, 43, 47],
        1: [43, 50, 41, 50, 49, 46],
        2: [42, 49, 40, 47, 49, 45],
    },
    # Setup cost
    "setup_cost": {
        0: [1282, 1493, 1006, 1286, 1305, 1360],
        1: [1402, 1498, 1296, 1366, 1376, 1172],
        2: [1362, 1094, 1283, 1279, 1430, 1146],
    },
    # Inventory holding cost per unit
    "hold_cost": {
        0: [4, 5, 4, 5, 4, 4],
        1: [5, 5, 5, 4, 4, 4],
        2: [5, 5, 4, 5, 5, 4],
    },
    # Monthly resource capacity (units)
    "resource_cap": [1173, 1102, 1018, 1077, 1190, 1132],
    # Resource consumption per unit of product
    "res_usage": {0: 1.778, 1: 1.502, 2: 1.556},
    # Max production per month if setup
    "max_prod": {
        0: [469, 394, 328, 228, 154, 83],
        1: [390, 325, 239, 162, 104, 52],
        2: [428, 371, 285, 235, 165, 65],
    },
}

GOLD_ANSWER = None


def _demand_by_period(cum):
    """Convert cumulative demands to per-period demands."""
    by_period = {}
    for idx, t in enumerate(range(len(cum))):
        if idx == 0:
            by_period[t] = cum[idx]
        else:
            by_period[t] = cum[idx] - cum[idx - 1]
    return by_period


def build_model(data=None):
    d = data or DATA
    P = d["products"]
    T = d["periods"]

    # per-period demand lookup
    demand = {p: _demand_by_period(d["cum_demand"][p]) for p in P}

    m = pyo.ConcreteModel()

    m.P = pyo.Set(initialize=P)
    m.T = pyo.Set(initialize=T)

    # --- Variables ---
    def x_bounds(m, p, t):
        return (0, d["max_prod"][p][t])

    m.x = pyo.Var(m.P, m.T, within=pyo.NonNegativeReals, bounds=x_bounds)
    m.I = pyo.Var(m.P, m.T, within=pyo.NonNegativeReals)
    m.y = pyo.Var(m.P, m.T, within=pyo.Binary)

    # --- Objective: production + setup + inventory holding ---
    def obj_rule(m):
        prod = sum(
            d["prod_cost"][p][t] * m.x[p, t] for p in P for t in T
        )
        setup = sum(
            d["setup_cost"][p][t] * m.y[p, t] for p in P for t in T
        )
        hold = sum(
            d["hold_cost"][p][t] * m.I[p, t] for p in P for t in T
        )
        return prod + setup + hold

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- Inventory balance constraint ---
    def balance_rule(m, p, t):
        if t == 0:
            prev_inv = 0
        else:
            prev_inv = m.I[p, t - 1]
        return prev_inv + m.x[p, t] - m.I[p, t] == demand[p][t]

    m.balance = pyo.Constraint(m.P, m.T, rule=balance_rule)

    # --- Final inventory must be zero ---
    def final_inv_rule(m, p):
        return m.I[p, T[-1]] == 0

    m.final_inv = pyo.Constraint(m.P, rule=final_inv_rule)

    # --- Setup linking: x[p,t] <= maxprod * y[p,t] ---
    def setup_link_rule(m, p, t):
        return m.x[p, t] <= d["max_prod"][p][t] * m.y[p, t]

    m.setup_link = pyo.Constraint(m.P, m.T, rule=setup_link_rule)

    # --- Resource capacity constraint ---
    def resource_rule(m, t):
        return (
            sum(d["res_usage"][p] * m.x[p, t] for p in P)
            <= d["resource_cap"][t]
        )

    m.resource = pyo.Constraint(m.T, rule=resource_rule)

    return m
